/* All scene controls are independent; preview and export share vector renderers. */
window.CollectorBackdrop=(()=>{
const color=(k,l,v)=>[k,l,'color',v],range=(k,l,v,min=0,max=100,step=1,unit='%')=>[k,l,'range',v,min,max,step,unit],check=(k,l,v)=>[k,l,'checkbox',v],select=(k,l,v,opts)=>[k,l,'select',v,opts];
const groups=[['渐变底色',[
check('gradientEnabled','启用渐变',true),color('background','画布底色','#77877d'),select('gradientMode','渐变类型',0,['线性','径向']),color('gradientA','色标 A','#505f56'),range('stopA','A 位置',0),color('gradientB','色标 B','#77877d'),range('stopB','B 位置',57),color('gradientC','色标 C','#cfdfda'),range('stopC','C 位置',100),range('gradientAngle','线性方向',90,0,360,1,'°'),range('gradientX','径向中心 X',50),range('gradientY','径向中心 Y',40),range('gradientRadius','径向范围',75,5,150)]],
['影棚光场',[
check('softEnabled','启用柔光',true),color('softColor','柔光颜色','#e1ede1'),range('studioLight','柔光强度',39),range('softX','柔光 X',37,-50,150),range('softY','柔光 Y',34,-50,150),range('softWidth','柔光宽度',70,5,150),range('softHeight','柔光高度',64,5,150),
check('floorEnabled','启用地面光',true),color('floorColor','地面光颜色','#cfdfda'),range('floorStrength','地面光强度',58),range('floorX','地面光 X',53,-50,150),range('floorY','地面光 Y',81,0,120),range('floorWidth','地面光宽度',76,5,150),range('floorHeight','地面光高度',21,1,80),
check('spaceShadowEnabled','启用空间投影',true),color('spaceShadowColor','投影颜色','#37483e'),range('spaceShadowStrength','投影强度',16),range('spaceShadowX','投影 X',50),range('spaceShadowY','投影 Y',72),range('spaceShadowWidth','投影宽度',29,1,100),range('spaceShadowHeight','投影厚度',4,1,40)]],
['透视网格 · 蒸汽波',[
check('perspectiveEnabled','启用透视网格',false),color('perspectiveColor','网格颜色','#b9a0ff'),range('perspectiveOpacity','网格透明度',65),range('horizon','地平线 Y',52,5,95),range('vanishingX','消失点 X',50,-50,150),range('rayCount','纵向密度',28,4,80,1,''),range('rowCount','横向密度',18,2,60,1,''),range('gridDepth','透视压缩',2.4,1,5,.1,''),range('perspectiveWidth','线宽',1,.2,5,.1,'px'),range('perspectiveGlow','辉光范围',5,0,25,.5,'px'),range('perspectiveGlowStrength','辉光强度',65),check('horizonEnabled','显示地平线',true)]],
['前景规范线 · CV 分析',[
check('overlayEnabled','启用前景分析层',false),color('overlayColor','线条／标记颜色','#ecf2df'),range('overlayOpacity','前景透明度',65),range('overlayWidth','线宽',.8,.2,4,.1,'px'),range('overlayMargin','安全边距',6,0,30),
check('flatGridEnabled','显示平面网格',true),range('overlayColumns','网格列数',4,1,16,1,''),range('overlayRows','网格行数',4,1,16,1,''),check('circlesEnabled','显示规范圆弧',true),range('circleCount','圆弧数量',2,1,6,1,''),range('circleRadius','圆弧半径',44,5,100),range('circleX','圆弧中心 X',50),range('circleY','圆弧中心 Y',50,-50,150),
check('markersEnabled','显示交点标记',true),range('markerSize','标记大小',5,1,16,.5,'px'),select('markerStyle','标记形态',0,['十字','方块','圆环']),
check('cvEnabled','显示设计检测框',false),range('cvX','框 X',22,0,90),range('cvY','框 Y',18,0,90),range('cvWidth','框宽度',56,5,100),range('cvHeight','框高度',54,5,100),range('cvCorners','角标长度',18,2,60,1,'px'),
check('numbersEnabled','显示数字与坐标',true),range('numberCount','数字数量',8,1,30,1,''),range('numberSize','数字字号',9,5,20,.5,'px'),color('numberColor','数字颜色','#ecf2df')]],
['画布信息', [color('canvasInk','画布文字颜色','#273b30'),check('infoEnabled','显示唱片信息',true)]]];
const fields=groups.flatMap(g=>g[1]),defaults=Object.fromEntries(fields.map(f=>[f[0],f[3]]));
function validate(s){for(const f of fields){const k=f[0],v=s[k];if(f[2]==='range')s[k]=Number.isFinite(v)?Math.min(f[5],Math.max(f[4],v)):f[3];if(f[2]==='select')s[k]=Number.isInteger(v)&&v>=0&&v<f[4].length?v:f[3];if(f[2]==='color'&&!/^#[0-9a-f]{6}$/i.test(v))s[k]=f[3];if(f[2]==='checkbox'&&typeof v!=='boolean')s[k]=f[3];}return s;}
const svg=(body,w,h)=>`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 1000 1000" preserveAspectRatio="none">${body}</svg>`;
const glow=(id,c,a)=>`<radialGradient id="${id}"><stop stop-color="${c}" stop-opacity="${a/100}"/><stop offset="1" stop-color="${c}" stop-opacity="0"/></radialGradient>`;
function render(s,w=1000,h=1000){const a=s.gradientAngle*Math.PI/180,dx=Math.cos(a)/2,dy=Math.sin(a)/2,stops=[[s.stopA,s.gradientA],[s.stopB,s.gradientB],[s.stopC,s.gradientC]].sort((a,b)=>a[0]-b[0]).map(([p,c])=>`<stop offset="${p}%" stop-color="${c}"/>`).join('');
let out=`<defs>${s.gradientMode===0?`<linearGradient id="lab-gradient" x1="${.5-dx}" y1="${.5-dy}" x2="${.5+dx}" y2="${.5+dy}">${stops}</linearGradient>`:`<radialGradient id="lab-gradient" cx="${s.gradientX}%" cy="${s.gradientY}%" r="${s.gradientRadius}%">${stops}</radialGradient>`}${glow('lab-soft',s.softColor,s.studioLight)}${glow('lab-floor',s.floorColor,s.floorStrength)}${glow('lab-shadow',s.spaceShadowColor,s.spaceShadowStrength)}</defs><rect width="1000" height="1000" fill="${s.background}"/>`;
if(s.gradientEnabled)out+='<rect width="1000" height="1000" fill="url(#lab-gradient)"/>';
for(const [enabled,prefix,id] of [['softEnabled','soft','lab-soft'],['floorEnabled','floor','lab-floor'],['spaceShadowEnabled','spaceShadow','lab-shadow']])if(s[enabled])out+=`<ellipse cx="${s[prefix+'X']*10}" cy="${s[prefix+'Y']*10}" rx="${s[prefix+'Width']*10}" ry="${s[prefix+'Height']*10}" fill="url(#${id})"/>`;
if(s.perspectiveEnabled){let d='',y=s.horizon*10,x=s.vanishingX*10;for(let i=0;i<=s.rayCount;i++)d+=`M${x},${y}L${-2000+i*5000/s.rayCount},1000`;for(let i=1;i<=s.rowCount;i++)d+=`M0,${y+(1000-y)*Math.pow(i/s.rowCount,s.gridDepth)}H1000`;if(s.horizonEnabled)d+=`M0,${y}H1000`;out+=`<defs><filter id="lab-neon" x="-100%" y="-100%" width="300%" height="300%"><feGaussianBlur stdDeviation="${s.perspectiveGlow*1000/w}"/></filter></defs><g fill="none" stroke="${s.perspectiveColor}" stroke-width="${s.perspectiveWidth*1000/w}" opacity="${s.perspectiveOpacity/100}"><path d="${d}" filter="url(#lab-neon)" opacity="${s.perspectiveGlowStrength/100}"/><path d="${d}"/></g>`;}return svg(out,w,h);}
function overlay(s,w=1000,h=1000){if(!s.overlayEnabled)return '';const u=1000/w,m=s.overlayMargin*10,span=1000-m*2;let d='',marks='',text='';
if(s.flatGridEnabled){for(let i=0;i<=s.overlayColumns;i++)d+=`M${m+i*span/s.overlayColumns},${m}V${1000-m}`;for(let j=0;j<=s.overlayRows;j++)d+=`M${m},${m+j*span/s.overlayRows}H${1000-m}`;}
if(s.circlesEnabled)for(let i=0;i<s.circleCount;i++)marks+=`<circle cx="${s.circleX*10}" cy="${s.circleY*10+(i-(s.circleCount-1)/2)*s.circleRadius*20}" r="${s.circleRadius*10}"/>`;
if(s.markersEnabled)for(let i=0;i<=s.overlayColumns;i++)for(let j=0;j<=s.overlayRows;j++){const x=m+i*span/s.overlayColumns,y=m+j*span/s.overlayRows,r=s.markerSize*u;marks+=s.markerStyle===0?`<path d="M${x-r},${y}h${r*2}M${x},${y-r}v${r*2}"/>`:s.markerStyle===1?`<rect x="${x-r/2}" y="${y-r/2}" width="${r}" height="${r}" fill="${s.overlayColor}"/>`:`<circle cx="${x}" cy="${y}" r="${r/2}"/>`;}
if(s.cvEnabled){const x=s.cvX*10,y=s.cvY*10,cw=s.cvWidth*10,ch=s.cvHeight*10,r=s.cvCorners*u;marks+=`<rect x="${x}" y="${y}" width="${cw}" height="${ch}" stroke-dasharray="${3*u} ${5*u}" opacity=".45"/><path d="M${x+r},${y}H${x}V${y+r}M${x+cw-r},${y}H${x+cw}V${y+r}M${x},${y+ch-r}V${y+ch}H${x+r}M${x+cw-r},${y+ch}H${x+cw}V${y+ch-r}"/><circle cx="${x+cw/2}" cy="${y+ch/2}" r="${4*u}"/>`;text+=`<text x="${x}" y="${y-8*u}">OBJECT / MD-001 · REGION</text>`;}
if(s.numbersEnabled)for(let i=0;i<s.numberCount;i++){const x=m+i%3*span/3,y=m+Math.floor(i/3)*span/Math.ceil(s.numberCount/3);text+=`<text x="${x+8*u}" y="${y+15*u}">${String(i+1).padStart(2,'0')} / X:${(x/10).toFixed(1)} Y:${(y/10).toFixed(1)}</text>`;}
return svg(`<g opacity="${s.overlayOpacity/100}"><g fill="none" stroke="${s.overlayColor}" stroke-width="${s.overlayWidth*u}"><path d="${d}"/>${marks}</g><g fill="${s.numberColor}" font-family="monospace" font-size="${s.numberSize*u}">${text}</g></g>`,w,h);}
function paint(s,screen){screen.style.setProperty('--scene-backdrop',`url("data:image/svg+xml,${encodeURIComponent(render(s,screen.clientWidth,screen.clientHeight))}")`);screen.style.setProperty('--scene-ink',s.canvasInk);screen.dataset.studio='true';screen.dataset.info=String(s.infoEnabled);let el=document.getElementById('scene-overlay');if(!el){el=document.createElement('div');el.id='scene-overlay';el.setAttribute('aria-hidden','true');screen.append(el);}el.innerHTML=overlay(s,screen.clientWidth,screen.clientHeight);}
function mount(C){const root=document.getElementById('scene-lab'),s=C.settings;function sync(){root.querySelectorAll('[data-scene]').forEach(el=>{const f=fields.find(f=>f[0]===el.dataset.scene);if(el.type==='checkbox')el.checked=s[f[0]];else el.value=s[f[0]];const o=el.parentElement.querySelector('output');if(o)o.textContent=s[f[0]]+(f[7]||'');});}
root.innerHTML='<p class="lab-hint">独立图层，自由叠加。线宽／字号／辉光以画布像素计；检测框是可调设计装饰，不是自动识别。</p>'+groups.map(([name,fs],i)=>`<details class="lab-group" ${i===0?'open':''}><summary>${name}<small>${String(i+1).padStart(2,'0')}</small></summary><div class="lab-fields">${fs.map(f=>`<label class="${f[2]==='checkbox'?'check':''}">${f[2]==='checkbox'?`<input aria-label="${f[1]}" data-scene="${f[0]}" type="checkbox">`:''}<span>${f[1]}</span>${f[2]==='range'?`<output></output><input aria-label="${f[1]}" data-scene="${f[0]}" type="range" min="${f[4]}" max="${f[5]}" step="${f[6]}">`:f[2]==='color'?`<input aria-label="${f[1]}" data-scene="${f[0]}" type="color">`:f[2]==='select'?`<select aria-label="${f[1]}" data-scene="${f[0]}">${f[4].map((x,j)=>`<option value="${j}">${x}</option>`).join('')}</select>`:''}</label>`).join('')}<button type="button" data-reset="${i}">重置本组</button></div></details>`).join('')+'<div class="lab-save"><button id="save-look">保存视觉参数 JSON</button><button id="load-look">载入视觉参数</button><input id="look-file" type="file" accept=".json,application/json" hidden></div>';
root.addEventListener('input',e=>{const el=e.target,k=el.dataset.scene;if(!k)return;s[k]=el.type==='checkbox'?el.checked:el.type==='color'?el.value:+el.value;sync();C.paint();C.persist();});root.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>{groups[+b.dataset.reset][1].forEach(f=>s[f[0]]=f[3]);sync();C.paint();C.persist();});
root.querySelector('#save-look').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,visual:Object.fromEntries(fields.map(f=>[f[0],s[f[0]]]))},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='md-visual-parameters.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};root.querySelector('#load-look').onclick=()=>root.querySelector('#look-file').click();root.querySelector('#look-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('参数文件过大');const raw=JSON.parse(await f.text());if(raw.version!==1||!raw.visual||typeof raw.visual!=='object')throw Error('不是视觉参数文件');const next=validate({...defaults,...raw.visual});fields.forEach(f=>s[f[0]]=next[f[0]]);sync();C.paint();C.persist();C.notice('已载入视觉参数');}catch(err){C.notice('载入失败：'+err.message);}e.target.value='';};sync();return sync;}
return {defaults,validate,render,overlay,paint,mount};
})();
